import sqlite3

import stripe

DB_PATH = "library.db"
PRICES_CENTS = {"4x6": 25, "5x7": 60, "8x10": 150, "16x20": 1200}


def order_photo_print(photo_id: int, size: str, quantity: int, stripe_customer_id: str) -> dict:
    if size not in PRICES_CENTS:
        return {"ok": False, "error": f"unsupported size {size}"}
    if quantity < 1 or quantity > 50:
        return {"ok": False, "error": "quantity must be between 1 and 50"}
    if not stripe_customer_id.startswith("cus_"):
        return {"ok": False, "error": "invalid customer id"}
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute("SELECT file_name FROM photos WHERE id = ?", (photo_id,)).fetchone()
    conn.close()
    if row is None:
        return {"ok": False, "error": "photo not found"}
    intent = stripe.PaymentIntent.create(
        amount=PRICES_CENTS[size] * quantity,
        currency="usd",
        customer=stripe_customer_id,
        confirm=True,
        off_session=True,
        description=f"{quantity} x {size} print of {row[0]}",
    )
    return {"ok": True, "payment_id": intent.id, "status": intent.status, "file_name": row[0]}

import sqlite3
from contextlib import closing
from datetime import datetime, timezone

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("photo-library")

DB_PATH = "library.db"
ALLOWED_ROLES = ("editor", "viewer")


def _demote_owner(conn: sqlite3.Connection, album_id: int, role: str) -> int:
    cur = conn.execute(
        "UPDATE album_members SET role = ? WHERE album_id = ? AND role = 'owner'",
        (role, album_id),
    )
    return cur.rowcount


def _promote_user(conn: sqlite3.Connection, album_id: int, user_id: int) -> None:
    conn.execute(
        "INSERT INTO album_members (album_id, user_id, role) VALUES (?, ?, 'owner') "
        "ON CONFLICT(album_id, user_id) DO UPDATE SET role = 'owner'",
        (album_id, user_id),
    )


def _log_transfer(conn: sqlite3.Connection, album_id: int, user_id: int, reason: str) -> None:
    conn.execute(
        "INSERT INTO album_activity (album_id, action, user_id, note, created_at) "
        "VALUES (?, 'ownership_transferred', ?, ?, ?)",
        (album_id, user_id, reason, datetime.now(timezone.utc).isoformat()),
    )


@mcp.tool()
def transfer_album_ownership(
    album_id: int,
    new_owner_id: int,
    previous_owner_role: str = "editor",
    reason: str = "",
) -> dict:
    if previous_owner_role not in ALLOWED_ROLES:
        return {"ok": False, "error": "previous_owner_role must be editor or viewer"}
    with closing(sqlite3.connect(DB_PATH)) as conn:
        with conn:
            demoted = _demote_owner(conn, album_id, previous_owner_role)
            if demoted == 0:
                return {"ok": False, "error": "album not found or has no owner"}
            _promote_user(conn, album_id, new_owner_id)
            conn.execute("UPDATE albums SET owner_id = ? WHERE id = ?", (new_owner_id, album_id))
            _log_transfer(conn, album_id, new_owner_id, reason)
    return {
        "ok": True,
        "album_id": album_id,
        "new_owner_id": new_owner_id,
        "previous_owner_role": previous_owner_role,
    }
